// src/modules/transaction/schemas.ts
var createTransactionSchema = external_exports.object({
  accountId: external_exports.string().min(1, "Akun wajib dipilih"),
  categoryId: external_exports.string().optional(),
  type: external_exports.enum(["INCOME", "EXPENSE", "TRANSFER"]),
  amount: external_exports.number().positive("Jumlah harus positif"),
  adminFee: external_exports.number().min(0, "Biaya admin tidak boleh negatif").optional(),
  description: external_exports.string().default(""),
  note: external_exports.string().optional(),
  date: external_exports.coerce.date(),
  receiptUrl: external_exports.string().url().optional(),
  fromAccountId: external_exports.string().optional(),
  toAccountId: external_exports.string().optional(),
  isRecurring: external_exports.boolean().default(false),
  recurringPattern: external_exports.object({
    frequency: external_exports.enum(["DAILY", "WEEKLY", "MONTHLY", "YEARLY"]),
    interval: external_exports.number().positive(),
    endDate: external_exports.date().optional()
  }).optional(),
  tagIds: external_exports.array(external_exports.string()).optional(),
  deductGoals: external_exports.boolean().default(false)
});
var updateTransactionSchema = createTransactionSchema.partial();
var createTransactionSchemaWithFee = createTransactionSchema.refine(
  (data) => {
    if (data.type !== "TRANSFER") return true;
    if (data.adminFee === void 0) return true;
    return data.adminFee <= data.amount;
  },
  { message: "Biaya admin tidak boleh lebih besar dari jumlah transfer", path: ["adminFee"] }
);
var transactionIdSchema = external_exports.object({
  id: external_exports.string().uuid("Invalid UUID format")
});
var transactionQuerySchema = external_exports.object({
  page: external_exports.coerce.number().int().positive().default(1),
  limit: external_exports.coerce.number().int().positive().max(100).default(20),
  accountId: external_exports.string().uuid().optional(),
  categoryId: external_exports.string().uuid().optional(),
  type: external_exports.enum(["INCOME", "EXPENSE", "TRANSFER"]).optional(),
  startDate: external_exports.coerce.date().optional(),
  endDate: external_exports.coerce.date().optional(),
  minAmount: external_exports.coerce.number().optional(),
  maxAmount: external_exports.coerce.number().optional(),
  search: external_exports.string().optional()
});

// src/modules/transaction/controller.ts
async function getTransactionsHandler(request, reply) {
  const query = transactionQuerySchema.parse(request.query);
  const result = await transactionService.getAll(request.user.id, query);
  return reply.send(result);
}
async function getTransactionHandler(request, reply) {
  const { id } = transactionIdSchema.parse(request.params);
  const transaction = await transactionService.getById(id, request.user.id);
  return reply.send({ transaction });
}
async function createTransactionHandler(request, reply) {
  try {
    const input = createTransactionSchema.parse(request.body);
    const transaction = await transactionService.create(request.user.id, input);
    return reply.status(201).send({ transaction });
  } catch (error) {
    if (error instanceof Error) {
      return reply.status(400).send({ error: error.message });
    }
    return reply.status(500).send({ error: "Terjadi kesalahan" });
  }
}
async function updateTransactionHandler(request, reply) {
  const { id } = transactionIdSchema.parse(request.params);
  const input = updateTransactionSchema.parse(request.body);
  const transaction = await transactionService.update(id, request.user.id, input);
  return reply.send({ transaction });
}
async function deleteTransactionHandler(request, reply) {
  const { id } = transactionIdSchema.parse(request.params);
  await transactionService.delete(id, request.user.id);
  return reply.status(204).send();
}
async function getRecentTransactionsHandler(request, reply) {
  const limit = parseInt(request.query.limit || "5", 10);
  const transactions = await transactionService.getRecent(request.user.id, limit);
  return reply.send({ transactions });
}
async function getSummaryHandler(request, reply) {
  const startDate = new Date(request.query.startDate);
  const endDate = new Date(request.query.endDate);
  const summary = await transactionService.getSummary(request.user.id, startDate, endDate);
  return reply.send(summary);
}

// src/modules/transaction/routes.ts
async function transactionRoutes(fastify2) {
  fastify2.addHook("preHandler", authenticate);
  fastify2.get("/", {
    schema: {
      querystring: {
        type: "object",
        properties: {
          page: { type: "number", default: 1 },
          limit: { type: "number", default: 20 },
          accountId: { type: "string" },
          categoryId: { type: "string" },
          type: { type: "string" },
          startDate: { type: "string" },
          endDate: { type: "string" },
          search: { type: "string" }
        }
      }
    }
  }, getTransactionsHandler);
  fastify2.get("/recent", {
    schema: {
      querystring: {
        type: "object",
        properties: { limit: { type: "number", default: 5 } }
      }
    }
  }, getRecentTransactionsHandler);
  fastify2.get("/summary", {
    schema: {
      querystring: {
        type: "object",
        required: ["startDate", "endDate"],
        properties: {
          startDate: { type: "string" },
          endDate: { type: "string" }
        }
      }
    }
  }, getSummaryHandler);
  fastify2.get("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string" } } }
    }
  }, getTransactionHandler);
  fastify2.post("/", {
    schema: {
      body: {
        type: "object",
        required: ["accountId", "type", "amount"],
        properties: {
          accountId: { type: "string" },
          categoryId: { type: "string" },
          type: { type: "string", enum: ["INCOME", "EXPENSE", "TRANSFER"] },
          amount: { type: "number" },
          description: { type: "string" },
          date: { type: "string" },
          fromAccountId: { type: "string" },
          toAccountId: { type: "string" }
        }
      }
    }
  }, createTransactionHandler);
  fastify2.put("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string" } } }
    }
  }, updateTransactionHandler);
  fastify2.delete("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string" } } }
    }
  }, deleteTransactionHandler);
}

