// src/modules/budget/schemas.ts
var createBudgetSchema = external_exports.object({
  categoryId: external_exports.string().uuid("Invalid category ID"),
  amount: external_exports.number().positive("Jumlah anggaran harus positif"),
  period: external_exports.enum(["MONTHLY", "WEEKLY", "YEARLY", "CUSTOM"]).default("MONTHLY"),
  startDate: external_exports.coerce.date(),
  endDate: external_exports.coerce.date().optional(),
  warningThreshold: external_exports.number().int().min(0).max(100).default(80),
  isActive: external_exports.boolean().default(true)
});
var updateBudgetSchema = createBudgetSchema.partial();
var budgetIdSchema = external_exports.object({
  id: external_exports.string().uuid("Invalid UUID format")
});

// src/modules/budget/controller.ts
async function getBudgetsHandler(request, reply) {
  const budgets = await budgetService.getAllWithSpending(request.user.id, request.query.month);
  return reply.send({ budgets });
}
async function getBudgetSummaryHandler(request, reply) {
  const summary = await budgetService.getSummary(request.user.id, request.query.month);
  return reply.send(summary);
}
async function getBudgetHandler(request, reply) {
  const { id } = budgetIdSchema.parse(request.params);
  const budget = await budgetService.getSpending(request.user.id, id);
  return reply.send(budget);
}
async function createBudgetHandler(request, reply) {
  const input = createBudgetSchema.parse(request.body);
  const budget = await budgetService.create(request.user.id, input);
  return reply.status(201).send({ budget });
}
async function updateBudgetHandler(request, reply) {
  const { id } = budgetIdSchema.parse(request.params);
  const input = updateBudgetSchema.parse(request.body);
  const budget = await budgetService.update(id, request.user.id, input);
  return reply.send({ budget });
}
async function updateBudgetSpentHandler(request, reply) {
  const { id } = budgetIdSchema.parse(request.params);
  const { spent } = request.body;
  const budget = await budgetService.updateSpent(id, request.user.id, spent);
  return reply.send({ budget });
}
async function deleteBudgetHandler(request, reply) {
  const { id } = budgetIdSchema.parse(request.params);
  await budgetService.delete(id, request.user.id);
  return reply.status(204).send();
}

// src/modules/budget/routes.ts
async function budgetRoutes(fastify2) {
  fastify2.addHook("preHandler", authenticate);
  fastify2.get("/", {}, getBudgetsHandler);
  fastify2.get("/summary", {}, getBudgetSummaryHandler);
  fastify2.put("/:id/spent", {}, updateBudgetSpentHandler);
  fastify2.get("/:id", {}, getBudgetHandler);
  fastify2.post("/", {}, createBudgetHandler);
  fastify2.put("/:id", {}, updateBudgetHandler);
  fastify2.delete("/:id", {}, deleteBudgetHandler);
}

