async function deleteGoalWithRefundHandler(request, reply) {
  const { id } = goalIdSchema.parse(request.params);
  const { refundAccountId } = request.query;
  try {
    const result = await goalService.deleteWithRefund(id, request.user.id, refundAccountId);
    return reply.send(result);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    return reply.status(400).send({ error: true, message });
  }
}
async function deleteContributionHandler(request, reply) {
  const { id: goalId, contributionId } = request.params;
  const userId = request.user.id;
  try {
    const result = await goalService.deleteContribution(goalId, contributionId, userId);
    return reply.send(result);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    if (message.includes("INITIAL")) {
      return reply.status(400).send({ error: message });
    }
    if (message.includes("tidak ditemukan")) {
      return reply.status(404).send({ error: message });
    }
    return reply.status(500).send({ error: "Gagal menghapus contribution" });
  }
}

// src/modules/goal/routes.ts
async function goalRoutes(fastify2) {
  fastify2.addHook("preHandler", authenticate);
  fastify2.get("/", {
    schema: {
      response: { 200: { type: "object", properties: { goals: { type: "array" } } } }
    }
  }, getGoalsHandler);
  fastify2.get("/overview", {
    schema: {
      response: { 200: { type: "object", properties: { totalTarget: { type: "number" }, totalSaved: { type: "number" }, progress: { type: "number" } } } }
    }
  }, getGoalsOverviewHandler);
  fastify2.get("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, getGoalHandler);
  fastify2.post("/", {
    schema: {
      body: {
        type: "object",
        required: ["name", "targetAmount", "deadline"],
        properties: {
          name: { type: "string" },
          targetAmount: { type: "number" },
          deadline: { type: "string" },
          icon: { type: "string", default: "target" },
          color: { type: "string", default: "#10B981" }
        }
      }
    }
  }, createGoalHandler);
  fastify2.put("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, updateGoalHandler);
  fastify2.delete("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, deleteGoalHandler);
  fastify2.post("/:id/contributions", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        required: ["amount", "date"],
        properties: {
          amount: { type: "number" },
          date: { type: "string" },
          note: { type: "string" }
        }
      }
    }
  }, addContributionHandler);
  fastify2.patch("/:id/lock", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, toggleLockHandler);
  fastify2.delete("/:id/with-transaction", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        properties: {
          accountId: { type: "string", format: "uuid" }
        }
      }
    }
  }, deleteGoalWithTransactionHandler);
  fastify2.get("/:id/contributions", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, getContributionsHandler);
  fastify2.post("/:id/contributions/with-account", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        required: ["amount", "date"],
        properties: {
          amount: { type: "number" },
          date: { type: "string" },
          note: { type: "string" },
          accountId: { type: "string" },
          categoryId: { type: "string" }
        }
      }
    }
  }, addContributionWithAccountHandler);
  fastify2.post("/from-milestone/:milestoneId", {
    schema: {
      params: { type: "object", properties: { milestoneId: { type: "string", format: "uuid" } } }
    }
  }, createGoalFromMilestoneHandler);
  fastify2.delete("/:id/with-refund", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      querystring: {
        type: "object",
        properties: {
          refundAccountId: { type: "string", format: "uuid" }
        }
      }
    }
  }, deleteGoalWithRefundHandler);
  fastify2.delete("/:id/contributions/:contributionId", {
    schema: {
      params: {
        type: "object",
        properties: {
          id: { type: "string", format: "uuid" },
          contributionId: { type: "string", format: "uuid" }
        }
      }
    }
  }, deleteContributionHandler);
}

