async function planRoutes(fastify2) {
  fastify2.addHook("preHandler", authenticate);
  fastify2.get("/", {
    schema: {
      response: { 200: { type: "object", properties: { plans: { type: "array" } } } }
    }
  }, getPlansHandler);
  fastify2.get("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, getPlanHandler);
  fastify2.post("/", {
    schema: {
      body: {
        type: "object",
        required: ["name", "startDate", "endDate"],
        properties: {
          name: { type: "string" },
          description: { type: "string" },
          startDate: { type: "string" },
          endDate: { type: "string" },
          status: { type: "string", enum: ["ACTIVE", "COMPLETED", "ARCHIVED"], default: "ACTIVE" }
        }
      }
    }
  }, createPlanHandler);
  fastify2.put("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, updatePlanHandler);
  fastify2.delete("/:id", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, deletePlanHandler);
  fastify2.post("/:id/milestones", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        required: ["title", "targetDate"],
        properties: {
          title: { type: "string" },
          description: { type: "string" },
          targetDate: { type: "string" },
          targetAmount: { type: "number" }
        }
      }
    }
  }, addMilestoneHandler);
  fastify2.put("/:id/milestones/reorder", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        properties: {
          milestones: {
            type: "array",
            items: {
              type: "object",
              properties: {
                id: { type: "string", format: "uuid" },
                order: { type: "number" }
              }
            }
          }
        }
      }
    }
  }, reorderMilestonesHandler);
  fastify2.put("/:planId/milestones/:milestoneId", {
    schema: {
      params: {
        type: "object",
        properties: {
          planId: { type: "string", format: "uuid" },
          milestoneId: { type: "string", format: "uuid" }
        }
      }
    }
  }, updateMilestoneHandler);
  fastify2.delete("/:planId/milestones/:milestoneId", {
    schema: {
      params: {
        type: "object",
        properties: {
          planId: { type: "string", format: "uuid" },
          milestoneId: { type: "string", format: "uuid" }
        }
      }
    }
  }, deleteMilestoneHandler);
  fastify2.patch("/:planId/milestones/:milestoneId/complete", {
    schema: {
      params: {
        type: "object",
        properties: {
          planId: { type: "string", format: "uuid" },
          milestoneId: { type: "string", format: "uuid" }
        }
      }
    }
  }, completeMilestoneHandler);
  fastify2.post("/:id/link-budget", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        required: ["budgetId"],
        properties: { budgetId: { type: "string", format: "uuid" } }
      }
    }
  }, linkBudgetHandler);
  fastify2.delete("/:id/link-budget/:budgetId", {
    schema: {
      params: {
        type: "object",
        properties: {
          id: { type: "string", format: "uuid" },
          budgetId: { type: "string", format: "uuid" }
        }
      }
    }
  }, async (request, reply) => {
    const { id, budgetId } = request.params;
    await planService.unlinkBudget(id, request.user.id, budgetId);
    return { success: true };
  });
  fastify2.post("/:id/link-goal", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } },
      body: {
        type: "object",
        required: ["goalId"],
        properties: { goalId: { type: "string", format: "uuid" } }
      }
    }
  }, linkGoalHandler);
  fastify2.delete("/:id/link-goal/:goalId", {
    schema: {
      params: {
        type: "object",
        properties: {
          id: { type: "string", format: "uuid" },
          goalId: { type: "string", format: "uuid" }
        }
      }
    }
  }, async (request, reply) => {
    const { id, goalId } = request.params;
    await planService.unlinkGoal(id, request.user.id, goalId);
    return { success: true };
  });
  fastify2.post("/:id/create-budgets-from-milestones", {
    schema: {
      params: { type: "object", properties: { id: { type: "string", format: "uuid" } } }
    }
  }, createBudgetsFromMilestonesHandler);
}

