// src/modules/search/service.ts
init_prisma();
var SearchService = class {
  async search(query, userId) {
    const { q, limit } = query;
    const searchPattern = { contains: q, mode: "insensitive" };
    const [transactions, accounts, categories, budgets, goals, plans] = await Promise.all([
      prisma.transaction.findMany({
        where: {
          userId,
          OR: [
            { description: searchPattern }
          ]
        },
        take: limit,
        orderBy: { date: "desc" },
        select: {
          id: true,
          description: true,
          date: true,
          amount: true
        }
      }),
      prisma.account.findMany({
        where: {
          userId,
          name: searchPattern
        },
        take: limit,
        select: {
          id: true,
          name: true,
          type: true
        }
      }),
      prisma.category.findMany({
        where: {
          userId,
          name: searchPattern
        },
        take: limit,
        select: {
          id: true,
          name: true,
          type: true
        }
      }),
      prisma.budget.findMany({
        where: {
          userId,
          category: { name: searchPattern }
        },
        take: limit,
        include: {
          category: { select: { name: true } }
        }
      }),
      prisma.goal.findMany({
        where: {
          userId,
          name: searchPattern
        },
        take: limit,
        select: {
          id: true,
          name: true,
          targetAmount: true,
          currentAmount: true
        }
      }),
      prisma.plan.findMany({
        where: {
          userId,
          name: searchPattern
        },
        take: limit,
        select: {
          id: true,
          name: true,
          status: true
        }
      })
    ]);
    const budgetsFormatted = budgets.map((b) => ({
      id: b.id,
      categoryName: b.category?.name || "",
      amount: b.amount
    }));
    return {
      transactions,
      accounts,
      categories,
      budgets: budgetsFormatted,
      goals,
      plans,
      total: transactions.length + accounts.length + categories.length + budgetsFormatted.length + goals.length + plans.length
    };
  }
};
var searchService = new SearchService();

// src/modules/search/schemas.ts
var searchQuerySchema = external_exports.object({
  q: external_exports.string().min(1).max(100),
  limit: external_exports.preprocess((val) => val ? parseInt(val, 10) : 5, external_exports.number().min(1).max(10).default(5))
});

// src/modules/search/controller.ts
async function searchController(fastify2) {
  fastify2.get(
    "/",
    {
      preHandler: [fastify2.authenticate]
    },
    async (request, reply) => {
      const userId = request.user?.id;
      if (!userId) {
        return reply.status(401).send({ message: "Unauthorized" });
      }
      const parsed = searchQuerySchema.safeParse(request.query);
      if (!parsed.success) {
        return reply.status(400).send({
          message: "Invalid query",
          errors: parsed.error.errors
        });
      }
      const result = await searchService.search(parsed.data, userId);
      return reply.send(result);
    }
  );
}

