var APP_PREFIX = {
  FINANCIAL_MANAGEMENT: "FM",
  EVENT_ORGANIZER: "EO"
};
async function createPayment(params) {
  const appPrefix = APP_PREFIX[params.app];
  const orderId = `${appPrefix}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  const pricing = await prisma.pricing.findFirst({
    where: { app: params.app, period: "MONTHLY", isActive: true }
  });
  if (!pricing) {
    throw new Error("Pricing not configured. Contact admin.");
  }
  let amount = pricing.amount;
  let couponId = null;
  if (params.couponCode) {
    const coupon = await prisma.coupon.findUnique({
      where: { code: params.couponCode }
    });
    if (coupon && coupon.isActive && /* @__PURE__ */ new Date() <= coupon.validUntil && /* @__PURE__ */ new Date() >= coupon.validFrom) {
      if (!coupon.maxUses || coupon.usedCount < coupon.maxUses) {
        couponId = coupon.id;
        if (coupon.type === "PERCENTAGE") {
          amount = Math.floor(amount * (1 - coupon.value / 100));
        } else {
          amount = Math.max(0, amount - coupon.value);
        }
      }
    }
  }
  const user = await prisma.user.findUnique({
    where: { id: params.userId }
  });
  if (!user) {
    throw new Error("User not found");
  }
  const payment = await prisma.payment.create({
    data: {
      userId: params.userId,
      app: params.app,
      amount: pricing.amount,
      finalAmount: amount,
      paymentMethod: params.paymentMethod,
      paymentProvider: params.paymentProvider,
      paymentType: params.paymentType,
      midtransOrderId: orderId,
      couponId,
      status: "PENDING"
    }
  });
  try {
    let token;
    let redirectUrl;
    if (params.paymentMethod === "CREDIT_CARD" && params.enableAutoRenewal) {
      const subscription = await createSubscription(
        user.name,
        user.email,
        params.paymentProvider,
        amount,
        orderId
      );
      await prisma.payment.update({
        where: { id: payment.id },
        data: {
          midtransToken: subscription.subscription_id
        }
      });
      token = subscription.token;
    } else {
      const result = await createMidtransTransaction({
        orderId,
        amount,
        customerName: user.name,
        customerEmail: user.email,
        paymentMethod: params.paymentMethod,
        paymentProvider: params.paymentProvider
      });
      await prisma.payment.update({
        where: { id: payment.id },
        data: {
          midtransTransactionId: result.transaction_id || orderId,
          vaNumber: result.vaNumber
        }
      });
      token = result.transaction_id || orderId;
      redirectUrl = result.redirect_url;
    }
    return {
      orderId: payment.midtransOrderId,
      token,
      redirectUrl
    };
  } catch (error) {
    await prisma.payment.update({
      where: { id: payment.id },
      data: {
        status: "FAILED",
        errorMessage: error instanceof Error ? error.message : "Unknown error"
      }
    });
    throw error;
  }
}
async function activateUserSubscription(payment) {
  const user = await prisma.user.findUnique({
    where: { id: payment.userId },
    select: { subscriptionTier: true, trialEndsAt: true }
  });
  if (!user) return;
  const startDate = /* @__PURE__ */ new Date();
  const endDate = /* @__PURE__ */ new Date();
  endDate.setMonth(endDate.getMonth() + 1);
  const updateData = {
    subscriptionTier: "PRO",
    subscriptionStartAt: startDate,
    subscriptionEndAt: endDate
  };
  if (user.subscriptionTier === "TRIAL") {
    updateData.trialStartedAt = null;
    updateData.trialEndsAt = null;
  }
  await prisma.user.update({
    where: { id: payment.userId },
    data: updateData
  });
  const existingSub = await prisma.subscription.findFirst({
    where: { userId: payment.userId, app: payment.app, status: "ACTIVE" }
  });
  if (existingSub) {
    await prisma.subscription.update({
      where: { id: existingSub.id },
      data: { startDate, endDate }
    });
  } else {
    await prisma.subscription.create({
      data: {
        userId: payment.userId,
        app: payment.app,
        tier: "PRO",
        startDate,
        endDate,
        status: "ACTIVE"
      }
    });
  }
}
async function handleMidtransCallback(orderId, status, transactionId, callbackData) {
  const payment = await prisma.payment.findFirst({
    where: { midtransOrderId: orderId }
  });
  if (!payment) {
    throw new Error("Payment not found");
  }
  let paymentStatus = "PENDING";
  if (status === "settlement" || status === "capture") {
    paymentStatus = "SUCCESS";
  } else if (status === "expire") {
    paymentStatus = "EXPIRED";
  } else if (status === "deny" || status === "cancel") {
    paymentStatus = "FAILED";
  }
  await prisma.payment.update({
    where: { id: payment.id },
    data: {
      status: paymentStatus,
      midtransTransactionId: transactionId,
      callbackData
    }
  });
  if (paymentStatus === "SUCCESS") {
    await activateUserSubscription(payment);
  }
  return { success: true };
}
async function getUserPayments(userId) {
  return prisma.payment.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
    include: { coupon: true }
  });
}
async function getPaymentById(paymentId) {
  return prisma.payment.findUnique({
    where: { id: paymentId },
    include: { coupon: true }
  });
}
async function getPaymentByOrderId(orderId) {
  const payment = await prisma.payment.findFirst({
    where: { midtransOrderId: orderId },
    include: { coupon: true, user: { select: { id: true, name: true, email: true } } }
  });
  if (!payment) {
    return null;
  }
  if (payment.status === "PENDING" && payment.midtransTransactionId) {
    try {
      const midtransData = await getTransactionStatus(payment.midtransTransactionId);
      const midtransStatus = midtransData.transaction_status;
      let newStatus = "PENDING";
      if (midtransStatus === "settlement" || midtransStatus === "capture") {
        newStatus = "SUCCESS";
      } else if (midtransStatus === "expire") {
        newStatus = "EXPIRED";
      } else if (midtransStatus === "deny" || midtransStatus === "cancel") {
        newStatus = "FAILED";
      }
      if (newStatus !== payment.status) {
        await prisma.payment.update({
          where: { id: payment.id },
          data: { status: newStatus }
        });
        payment.status = newStatus;
        if (newStatus === "SUCCESS") {
          await activateUserSubscription(payment);
        }
      }
    } catch (e) {
      console.error("Failed to sync with Midtrans:", e);
    }
  }
  const now = /* @__PURE__ */ new Date();
  const fifteenMinLater = new Date(payment.createdAt.getTime() + 15 * 60 * 1e3);
  let status = payment.status;
  if (status === "PENDING" && now > fifteenMinLater) {
    status = "EXPIRED";
  }
  return {
    orderId: payment.midtransOrderId,
    status,
    paymentMethod: payment.paymentMethod,
    paymentProvider: payment.paymentProvider,
    vaNumber: payment.vaNumber,
    amount: payment.finalAmount,
    expiredAt: payment.createdAt,
    qrUrl: null
  };
}
function getClientKey() {
  return midtransConfig.clientKey;
}

// src/modules/payment/payment.controller.ts
async function createPayment2(request, reply) {
  try {
    const user = request.user;
    if (!user?.id) {
      return reply.status(401).send({ error: "Unauthorized" });
    }
    const { app, paymentMethod, paymentProvider, paymentType, couponCode, enableAutoRenewal } = request.body;
    if (!app || !paymentMethod || !paymentType) {
      return reply.status(400).send({ error: "Missing required fields" });
    }
    const result = await createPayment({
      userId: user.id,
      app,
      paymentMethod,
      paymentProvider,
      paymentType,
      couponCode,
      enableAutoRenewal
    });
    return reply.send(result);
  } catch (error) {
    console.error("Create payment error:", error);
    return reply.status(500).send({ error: error instanceof Error ? error.message : "Payment failed" });
  }
}
async function handleCallback(request, reply) {
  try {
    const { order_id, transaction_status, transaction_id, ...callbackData } = request.body;
    await handleMidtransCallback(
      order_id,
      transaction_status,
      transaction_id,
      callbackData
    );
    return reply.send({ success: true });
  } catch (error) {
    console.error("Callback error:", error);
    return reply.status(500).send({ error: "Callback processing failed" });
  }
}
