// src/modules/admin/admin-users.service.ts
init_prisma();
var adminUsersService = {
  async listUsers(params) {
    const { page = 1, limit = 20, search, role, tier } = params;
    const pageNum = parseInt(page, 10) || 1;
    const limitNum = parseInt(limit, 10) || 20;
    const skip = (pageNum - 1) * limitNum;
    const where = {};
    if (search) {
      where.OR = [
        { name: { contains: search } },
        { email: { contains: search } }
      ];
    }
    if (role) where.role = role;
    if (tier) where.subscriptionTier = tier;
    const [users, total] = await Promise.all([
      prisma.user.findMany({
        where,
        skip,
        take: limitNum,
        orderBy: { createdAt: "desc" },
        select: {
          id: true,
          name: true,
          email: true,
          avatar: true,
          role: true,
          subscriptionTier: true,
          subscriptionEndAt: true,
          createdAt: true
        }
      }),
      prisma.user.count({ where })
    ]);
    return { users, total, page: pageNum, limit: limitNum, totalPages: Math.ceil(total / limitNum) };
  },
  async getUserById(id) {
    return prisma.user.findUnique({
      where: { id },
      include: {
        subscriptions: {
          orderBy: { createdAt: "desc" },
          take: 50
        }
      }
    });
  },
  async updateUser(id, data) {
    return prisma.user.update({
      where: { id },
      data: {
        name: data.name,
        role: data.role
      }
    });
  },
  async deleteUser(id) {
    return prisma.user.update({
      where: { id },
      data: { role: "MEMBER" }
    });
  },
  async resetPassword(id) {
    return { success: true, message: "Password reset email sent" };
  },
  async getUserActivity(userId) {
    return { logins: [], actions: [] };
  }
};

